<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {httpClient} from '@/shared/http/client'
import {workOrderApi,type WorkOrder,type RegionOption} from './work-orders'
const props=defineProps<{caseId:string;order:WorkOrder}>(),emit=defineEmits<{changed:[];pending:[value:boolean]}>(),api=workOrderApi(httpClient)
const address=ref(props.order.accidentAddress??''),region=ref(props.order.accidentRegionId),confirmed=ref(false),regions=ref<RegionOption[]>([]),page=ref(0),total=ref(0),busy=ref(false),error=ref(''),saved=ref(props.order.dispatchAddressConfirmed)
async function moreRegions(){busy.value=true;try{const data=await api.regions(page.value+1);regions.value.push(...data.records);page.value++;total.value=data.total}catch(e){error.value=e instanceof Error?e.message:'区域加载失败'}finally{busy.value=false}}
function changed(){confirmed.value=false;saved.value=false;emit('pending',true)}
async function save(){busy.value=true;error.value='';try{if(!region.value||!address.value.trim()||!confirmed.value)throw Error('请选择区域并核对实际接车地址');await api.dispatchLocation(props.caseId,props.order.version,region.value,address.value.trim());saved.value=true;emit('pending',false);emit('changed')}catch(e){error.value=e instanceof Error?e.message:'地址保存失败'}finally{busy.value=false}}
onMounted(moreRegions)
</script>
<template><section class="dispatch-location" data-reading="接车地址"><header><h3>接车地址</h3><span v-if="saved" class="confirmed">已确认</span></header><p>核对原文地址后确认，网点按模拟直线距离排序。</p><div class="location-fields"><label>服务区域<select v-model="region" :disabled="busy" @change="changed"><option :value="undefined">选择区域</option><option v-for="item in regions" :key="item.id" :value="item.id">{{ item.name }}（{{ item.code }}）</option></select></label><label>实际接车地址<input v-model="address" maxlength="255" :disabled="busy" placeholder="核对原文地址，补齐接车位置" @input="changed"/></label></div><button v-if="regions.length<total" :disabled="busy" @click="moreRegions">加载更多区域</button><label class="review"><input v-model="confirmed" type="checkbox" :disabled="busy"/>已与原文或联系人核对地址</label><button class="save-location" :disabled="busy||!confirmed" @click="save">{{ busy?'正在保存…':'确认地址并排列网点' }}</button><p v-if="error" role="alert">{{ error }}</p><small>当前使用地图Mock，模拟距离不代表实际地址或道路里程。</small></section></template>
<style scoped>.dispatch-location{padding:4px 0 24px;margin-bottom:24px;border-bottom:1px solid #dce5e4}.dispatch-location header{display:flex;align-items:center;gap:12px}.dispatch-location h3{margin:0}.dispatch-location p,.dispatch-location small{font-size:12px;color:#596a65}.location-fields{display:grid;grid-template-columns:1fr 2fr;gap:16px}.location-fields label{display:flex;flex-direction:column;gap:8px;font-size:13px}.location-fields input,.location-fields select{box-sizing:border-box;width:100%;padding:10px;border:1px solid #b9c9c9;border-radius:8px;background:white;font:inherit}.review{display:block;margin:16px 0;font-size:13px}.save-location{padding:10px 16px;border:0;border-radius:8px;background:#526f6d;color:white;cursor:pointer}.save-location:disabled{opacity:.5;cursor:default}.dispatch-location small{display:block;margin-top:12px}.confirmed{font-size:12px;color:#15803d}@media(max-width:700px){.location-fields{grid-template-columns:1fr}}</style>
